#!/usr/bin/env bash
# Loads a small synthetic dataset into Neo4j + Mongo for local dev/testing.
# Does NOT touch real production/dev data. Safe to run against a fresh,
# empty stack (docker compose up -d) instead of running bootstrap.sh with
# a real backup.json / centinela_db dump.
#
# Articles MOCK-ART-1..10 use title+abstract from dataset_qg_qa_sintetico.json
# (RAG / dense retrieval / hybrid search / vector indexing). Authors,
# affiliations, DOIs and dates are invented for local mock use.
set -Eeuo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

COMPOSE_FILE="${COMPOSE_FILE:-docker-compose.yaml}"
ENV_FILE="${ENV_FILE:-.env}"
COMPOSE=(docker compose -f "$COMPOSE_FILE")

log() { printf '[mock-seed] %s\n' "$*"; }
fail() { printf '[mock-seed] error: %s\n' "$*" >&2; exit 1; }

env_value() {
  local key="$1" default="${2:-}" value=""
  if [[ -n "${!key+x}" ]]; then
    value="${!key}"
  fi
  if [[ -z "$value" && -f "$ENV_FILE" ]]; then
    value="$(grep -E "^${key}=" "$ENV_FILE" | tail -n 1 | cut -d= -f2- || true)"
  fi
  # Strip Windows CRLF / surrounding quotes from .env values
  value="${value%$'\r'}"
  value="${value#\"}"
  value="${value%\"}"
  value="${value#\'}"
  value="${value%\'}"
  printf '%s' "${value:-$default}"
}

neo4j_user="$(env_value NEO4J_USERNAME neo4j)"
neo4j_password="$(env_value NEO4J_PASSWORD)"
[[ -n "$neo4j_password" ]] || fail "NEO4J_PASSWORD is required"

log "creating constraints"
"${COMPOSE[@]}" exec -T search-neo4j cypher-shell -u "$neo4j_user" -p "$neo4j_password" <<'CYPHER'
CREATE CONSTRAINT constraint_unique_Affiliation_scopus_id IF NOT EXISTS FOR (n:Affiliation) REQUIRE n.scopus_id IS UNIQUE;
CREATE CONSTRAINT constraint_unique_Article_scopus_id IF NOT EXISTS FOR (n:Article) REQUIRE n.scopus_id IS UNIQUE;
CREATE CONSTRAINT constraint_unique_Author_scopus_id IF NOT EXISTS FOR (n:Author) REQUIRE n.scopus_id IS UNIQUE;
CREATE CONSTRAINT constraint_unique_Topic_name IF NOT EXISTS FOR (n:Topic) REQUIRE n.name IS UNIQUE;
CYPHER

log "clearing previous MOCK-* nodes (idempotent re-seed)"
"${COMPOSE[@]}" exec -T search-neo4j cypher-shell -u "$neo4j_user" -p "$neo4j_password" <<'CYPHER'
MATCH (n)
WHERE n.scopus_id STARTS WITH "MOCK-"
DETACH DELETE n;
CYPHER

log "loading mock graph (3 affiliations, 5 authors, 10 articles from dataset_qg_qa_sintetico.json)"
"${COMPOSE[@]}" exec -T search-neo4j cypher-shell -u "$neo4j_user" -p "$neo4j_password" <<'CYPHER'
// Synthetic seed: 3 affiliations, 5 authors, 10 articles from dataset_qg_qa_sintetico.json
MERGE (a1:Affiliation {scopus_id:"MOCK-AFF-1"}) SET a1.name="Universidad Mock A";
MERGE (a2:Affiliation {scopus_id:"MOCK-AFF-2"}) SET a2.name="Universidad Mock B";
MERGE (a3:Affiliation {scopus_id:"MOCK-AFF-3"}) SET a3.name="Instituto Mock C";

MERGE (:Topic {name:"chatbots"});
MERGE (:Topic {name:"dense passage retrieval"});
MERGE (:Topic {name:"evaluation"});
MERGE (:Topic {name:"hybrid search"});
MERGE (:Topic {name:"indexing"});
MERGE (:Topic {name:"information retrieval"});
MERGE (:Topic {name:"large language models"});
MERGE (:Topic {name:"machine learning"});
MERGE (:Topic {name:"nlp"});
MERGE (:Topic {name:"question answering"});
MERGE (:Topic {name:"retrieval augmented generation"});
MERGE (:Topic {name:"vector databases"});

MERGE (au1:Author {scopus_id:"MOCK-AUTH-1"}) SET au1.first_name="Ana", au1.last_name="Gomez", au1.auth_name="Gomez, Ana", au1.initials="A.", au1.citation_count=42, au1.current_affiliation="Universidad Mock A";
MERGE (au2:Author {scopus_id:"MOCK-AUTH-2"}) SET au2.first_name="Luis", au2.last_name="Perez", au2.auth_name="Perez, Luis", au2.initials="L.", au2.citation_count=17, au2.current_affiliation="Universidad Mock A";
MERGE (au3:Author {scopus_id:"MOCK-AUTH-3"}) SET au3.first_name="Maria", au3.last_name="Diaz", au3.auth_name="Diaz, Maria", au3.initials="M.", au3.citation_count=30, au3.current_affiliation="Universidad Mock B";
MERGE (au4:Author {scopus_id:"MOCK-AUTH-4"}) SET au4.first_name="Carlos", au4.last_name="Ruiz", au4.auth_name="Ruiz, Carlos", au4.initials="C.", au4.citation_count=5, au4.current_affiliation="Instituto Mock C";
MERGE (au5:Author {scopus_id:"MOCK-AUTH-5"}) SET au5.first_name="Sofia", au5.last_name="Lopez", au5.auth_name="Lopez, Sofia", au5.initials="S.", au5.citation_count=63, au5.current_affiliation="Universidad Mock B";

MERGE (ar1:Article {scopus_id:"MOCK-ART-1"}) SET ar1.title="Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks", ar1.abstract="Large pre-trained language models have been shown to store factual knowledge in their parameters, and achieve state-of-the-art results when fine-tuned on downstream NLP tasks. However, their ability to access and precisely manipulate knowledge is still limited, and hence on knowledge-intensive tasks, their performance lags behind task-specific architectures. Additionally, providing provenance for their decisions and updating their world knowledge remain open research problems. Pre-trained models with a differentiable access mechanism to explicit non-parametric memory can overcome this issue, but have so far been only investigated for extractive downstream tasks. We explore a general-purpose fine-tuning recipe for retrieval-augmented generation (RAG) -- models which combine pre-trained parametric and non-parametric memory for language generation. We introduce RAG models where the parametric memory is a pre-trained seq2seq model and the non-parametric memory is a dense vector index of Wikipedia, accessed with a pre-trained neural retriever. We compare two RAG formulations, one which conditions on the same retrieved passages across the whole generated sequence, the other can use different passages per token. We fine-tune and evaluate our models on a wide range of knowledge-intensive NLP tasks and set the state-of-the-art on three open domain QA tasks, outperforming parametric seq2seq models and task-specific retrieve-and-extract architectures. For language generation tasks, we find that RAG models generate more specific, diverse and factual language than a state-of-the-art parametric-only seq2seq baseline.", ar1.doi="10.0000/mock-rag-1", ar1.publication_date="2020-05-22", ar1.author_count=2, ar1.affiliation_count=1, ar1.corpus="Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks Large pre-trained language models have been shown to store factual knowledge in their parameters, and achieve state-of-the-art results when fine-tuned on downstream NLP tasks. However, their ability to access and precisely manipulate knowledge is still limited, and hence on knowledge-intensive tasks, their performance lags behind task-specific architectures. Additionally, providing provenance for their decisions and updating their world knowledge remain open research problems. Pre-trained models with a differentiable access mechanism to explicit non-parametric memory can overcome this issue, but have so far been only investigated for extractive downstream tasks. We explore a general-purpose fine-tuning recipe for retrieval-augmented generation (RAG) -- models which combine pre-trained parametric and non-parametric memory for language generation. We introduce RAG models where the parametric memory is a pre-trained seq2seq model and the non-parametric memory is a dense vector index of Wikipedia, accessed with a pre-trained neural retriever. We compare two RAG formulations, one which conditions on the same retrieved passages across the whole generated sequence, the other can use different passages per token. We fine-tune and evaluate our models on a wide range of knowledge-intensive NLP tasks and set the state-of-the-art on three open domain QA tasks, outperforming parametric seq2seq models and task-specific retrieve-and-extract architectures. For language generation tasks, we find that RAG models generate more specific, diverse and factual language than a state-of-the-art parametric-only seq2seq baseline.";
MERGE (ar2:Article {scopus_id:"MOCK-ART-2"}) SET ar2.title="Retrieval-Augmented Generation for Large Language Models: A Survey", ar2.abstract="Large Language Models (LLMs) showcase impressive capabilities but encounter challenges like hallucination, outdated knowledge, and non-transparent, untraceable reasoning processes. Retrieval-Augmented Generation (RAG) has emerged as a promising solution by incorporating knowledge from external databases. This enhances the accuracy and credibility of the generation, particularly for knowledge-intensive tasks, and allows for continuous knowledge updates and integration of domain-specific information. RAG synergistically merges LLMs' intrinsic knowledge with the vast, dynamic repositories of external databases. This comprehensive review paper offers a detailed examination of the progression of RAG paradigms, encompassing the Naive RAG, the Advanced RAG, and the Modular RAG. It meticulously scrutinizes the tripartite foundation of RAG frameworks, which includes the retrieval, the generation and the augmentation techniques. The paper highlights the state-of-the-art technologies embedded in each of these critical components, providing a profound understanding of the advancements in RAG systems. Furthermore, this paper introduces up-to-date evaluation framework and benchmark. At the end, this article delineates the challenges currently faced and points out prospective avenues for research and development.", ar2.doi="10.0000/mock-rag-2", ar2.publication_date="2023-11-10", ar2.author_count=2, ar2.affiliation_count=1, ar2.corpus="Retrieval-Augmented Generation for Large Language Models: A Survey Large Language Models (LLMs) showcase impressive capabilities but encounter challenges like hallucination, outdated knowledge, and non-transparent, untraceable reasoning processes. Retrieval-Augmented Generation (RAG) has emerged as a promising solution by incorporating knowledge from external databases. This enhances the accuracy and credibility of the generation, particularly for knowledge-intensive tasks, and allows for continuous knowledge updates and integration of domain-specific information. RAG synergistically merges LLMs' intrinsic knowledge with the vast, dynamic repositories of external databases. This comprehensive review paper offers a detailed examination of the progression of RAG paradigms, encompassing the Naive RAG, the Advanced RAG, and the Modular RAG. It meticulously scrutinizes the tripartite foundation of RAG frameworks, which includes the retrieval, the generation and the augmentation techniques. The paper highlights the state-of-the-art technologies embedded in each of these critical components, providing a profound understanding of the advancements in RAG systems. Furthermore, this paper introduces up-to-date evaluation framework and benchmark. At the end, this article delineates the challenges currently faced and points out prospective avenues for research and development.";
MERGE (ar3:Article {scopus_id:"MOCK-ART-3"}) SET ar3.title="RAGAs: Automated Evaluation of Retrieval Augmented Generation", ar3.abstract="We introduce RAGAs (Retrieval Augmented Generation Assessment), a framework for reference-free evaluation of Retrieval Augmented Generation (RAG) pipelines. RAGAs is available at [https://github.com/explodinggradients/ragas]. RAG systems are composed of a retrieval and an LLM based generation module. They provide LLMs with knowledge from a reference textual database, enabling them to act as a natural language layer between a user and textual databases, thus reducing the risk of hallucinations. Evaluating RAG architectures is challenging due to several dimensions to consider: the ability of the retrieval system to identify relevant and focused context passages, the ability of the LLM to exploit such passages faithfully, and the quality of the generation itself. With RAGAs, we introduce a suite of metrics that can evaluate these different dimensions without relying on ground truth human annotations. We posit that such a framework can contribute crucially to faster evaluation cycles of RAG architectures, which is especially important given the fast adoption of LLMs.", ar3.doi="10.0000/mock-rag-3", ar3.publication_date="2023-09-15", ar3.author_count=2, ar3.affiliation_count=2, ar3.corpus="RAGAs: Automated Evaluation of Retrieval Augmented Generation We introduce RAGAs (Retrieval Augmented Generation Assessment), a framework for reference-free evaluation of Retrieval Augmented Generation (RAG) pipelines. RAGAs is available at [https://github.com/explodinggradients/ragas]. RAG systems are composed of a retrieval and an LLM based generation module. They provide LLMs with knowledge from a reference textual database, enabling them to act as a natural language layer between a user and textual databases, thus reducing the risk of hallucinations. Evaluating RAG architectures is challenging due to several dimensions to consider: the ability of the retrieval system to identify relevant and focused context passages, the ability of the LLM to exploit such passages faithfully, and the quality of the generation itself. With RAGAs, we introduce a suite of metrics that can evaluate these different dimensions without relying on ground truth human annotations. We posit that such a framework can contribute crucially to faster evaluation cycles of RAG architectures, which is especially important given the fast adoption of LLMs.";
MERGE (ar4:Article {scopus_id:"MOCK-ART-4"}) SET ar4.title="Dense Passage Retrieval for Open-Domain Question Answering", ar4.abstract="Open-domain question answering relies on efficient passage retrieval to select candidate contexts, where traditional sparse vector space models, such as TF-IDF or BM25, are the de facto method. In this work, we show that retrieval can be practically implemented using dense representations alone, where embeddings are learned from a small number of questions and passages by a simple dual-encoder framework. When evaluated on a wide range of open-domain QA datasets, our dense retriever outperforms a strong Lucene-BM25 system largely by 9%-19% absolute in terms of top-20 passage retrieval accuracy, and helps our end-to-end QA system establish new state-of-the-art on multiple open-domain QA benchmarks.", ar4.doi="10.0000/mock-dpr-1", ar4.publication_date="2020-04-10", ar4.author_count=2, ar4.affiliation_count=1, ar4.corpus="Dense Passage Retrieval for Open-Domain Question Answering Open-domain question answering relies on efficient passage retrieval to select candidate contexts, where traditional sparse vector space models, such as TF-IDF or BM25, are the de facto method. In this work, we show that retrieval can be practically implemented using dense representations alone, where embeddings are learned from a small number of questions and passages by a simple dual-encoder framework. When evaluated on a wide range of open-domain QA datasets, our dense retriever outperforms a strong Lucene-BM25 system largely by 9%-19% absolute in terms of top-20 passage retrieval accuracy, and helps our end-to-end QA system establish new state-of-the-art on multiple open-domain QA benchmarks.";
MERGE (ar5:Article {scopus_id:"MOCK-ART-5"}) SET ar5.title="RocketQA: An Optimized Training Approach to Dense Passage Retrieval for Open-Domain Question Answering", ar5.abstract="In open-domain question answering, dense passage retrieval has become a new paradigm to retrieve relevant passages for finding answers. Typically, the dual-encoder architecture is adopted to learn dense representations of questions and passages for semantic matching. However, it is difficult to effectively train a dual-encoder due to the challenges including the discrepancy between training and inference, the existence of unlabeled positives and limited training data. To address these challenges, we propose an optimized training approach, called RocketQA, to improving dense passage retrieval. We make three major technical contributions in RocketQA, namely cross-batch negatives, denoised hard negatives and data augmentation. The experiment results show that RocketQA significantly outperforms previous state-of-the-art models on both MSMARCO and Natural Questions. We also conduct extensive experiments to examine the effectiveness of the three strategies in RocketQA. Besides, we demonstrate that the performance of end-to-end QA can be improved based on our RocketQA retriever.", ar5.doi="10.0000/mock-dpr-2", ar5.publication_date="2021-07-18", ar5.author_count=2, ar5.affiliation_count=1, ar5.corpus="RocketQA: An Optimized Training Approach to Dense Passage Retrieval for Open-Domain Question Answering In open-domain question answering, dense passage retrieval has become a new paradigm to retrieve relevant passages for finding answers. Typically, the dual-encoder architecture is adopted to learn dense representations of questions and passages for semantic matching. However, it is difficult to effectively train a dual-encoder due to the challenges including the discrepancy between training and inference, the existence of unlabeled positives and limited training data. To address these challenges, we propose an optimized training approach, called RocketQA, to improving dense passage retrieval. We make three major technical contributions in RocketQA, namely cross-batch negatives, denoised hard negatives and data augmentation. The experiment results show that RocketQA significantly outperforms previous state-of-the-art models on both MSMARCO and Natural Questions. We also conduct extensive experiments to examine the effectiveness of the three strategies in RocketQA. Besides, we demonstrate that the performance of end-to-end QA can be improved based on our RocketQA retriever.";
MERGE (ar6:Article {scopus_id:"MOCK-ART-6"}) SET ar6.title="RocketQAv2: A Joint Training Method for Dense Passage Retrieval and Passage Re-ranking", ar6.abstract="In various natural language processing tasks, passage retrieval and passage re-ranking are two key procedures in finding and ranking relevant information. Since both the two procedures contribute to the final performance, it is important to jointly optimize them in order to achieve mutual improvement. In this paper, we propose a novel joint training approach for dense passage retrieval and passage reranking. A major contribution is that we introduce the dynamic listwise distillation, where we design a unified listwise training approach for both the retriever and the re-ranker. During the dynamic distillation, the retriever and the re-ranker can be adaptively improved according to each other’s relevance information. We also propose a hybrid data augmentation strategy to construct diverse training instances for listwise training approach. Extensive experiments show the effectiveness of our approach on both MSMARCO and Natural Questions datasets. Our code is available at https://github.com/PaddlePaddle/RocketQA.", ar6.doi="10.0000/mock-dpr-3", ar6.publication_date="2022-03-01", ar6.author_count=3, ar6.affiliation_count=2, ar6.corpus="RocketQAv2: A Joint Training Method for Dense Passage Retrieval and Passage Re-ranking In various natural language processing tasks, passage retrieval and passage re-ranking are two key procedures in finding and ranking relevant information. Since both the two procedures contribute to the final performance, it is important to jointly optimize them in order to achieve mutual improvement. In this paper, we propose a novel joint training approach for dense passage retrieval and passage reranking. A major contribution is that we introduce the dynamic listwise distillation, where we design a unified listwise training approach for both the retriever and the re-ranker. During the dynamic distillation, the retriever and the re-ranker can be adaptively improved according to each other’s relevance information. We also propose a hybrid data augmentation strategy to construct diverse training instances for listwise training approach. Extensive experiments show the effectiveness of our approach on both MSMARCO and Natural Questions datasets. Our code is available at https://github.com/PaddlePaddle/RocketQA.";
MERGE (ar7:Article {scopus_id:"MOCK-ART-7"}) SET ar7.title="One Blade for One Purpose: Advancing Math Information Retrieval using Hybrid Search", ar7.abstract="Neural retrievers have been shown to be effective for math-aware search. Their ability to cope with math symbol mismatches, to represent highly contextualized semantics, and to learn effective representations are critical to improving math information retrieval. However, the most effective retriever for math remains impractical as it depends on token-level dense representations for each math token, which leads to prohibitive storage demands, especially considering that math content generally consumes more tokens. In this work, we try to alleviate this efficiency bottleneck while boosting math information retrieval effectiveness via hybrid search. To this end, we propose MABOWDOR, a Math-Aware Bestof-Worlds Domain Optimized Retriever, which has an unsupervised structure search component, a dense retriever, and optionally a sparse retriever on top of a domain-adapted backbone learned by context-enhanced pretraining, each addressing a different need in retrieving heterogeneous data from math documents. Our hybrid search outperforms the previous state-of-the-art math IR system while eliminating efficiency bottlenecks. Our system is available at https://github.com/approach0/pya0.", ar7.doi="10.0000/mock-hyb-1", ar7.publication_date="2023-02-14", ar7.author_count=2, ar7.affiliation_count=1, ar7.corpus="One Blade for One Purpose: Advancing Math Information Retrieval using Hybrid Search Neural retrievers have been shown to be effective for math-aware search. Their ability to cope with math symbol mismatches, to represent highly contextualized semantics, and to learn effective representations are critical to improving math information retrieval. However, the most effective retriever for math remains impractical as it depends on token-level dense representations for each math token, which leads to prohibitive storage demands, especially considering that math content generally consumes more tokens. In this work, we try to alleviate this efficiency bottleneck while boosting math information retrieval effectiveness via hybrid search. To this end, we propose MABOWDOR, a Math-Aware Bestof-Worlds Domain Optimized Retriever, which has an unsupervised structure search component, a dense retriever, and optionally a sparse retriever on top of a domain-adapted backbone learned by context-enhanced pretraining, each addressing a different need in retrieving heterogeneous data from math documents. Our hybrid search outperforms the previous state-of-the-art math IR system while eliminating efficiency bottlenecks. Our system is available at https://github.com/approach0/pya0.";
MERGE (ar8:Article {scopus_id:"MOCK-ART-8"}) SET ar8.title="UNIguide: An Intelligent University Information Retrieval Chatbot Using Advanced Retrieval-Augmented Generation with Hybrid Search and Neural Re-Ranking", ar8.abstract="Accessing timely and accurate institutional infor-mation remains a challenge for students and faculty in en-gineering colleges. This paper presents UNIguide, a domain-specific intelligent chatbot designed to answer university-related queries using a Retrieval-Augmented Generation (RAG) pipeline integrating hybrid retrieval, neural re-ranking, query validation, and semantic caching. Hybrid retrieval combines dense vector search with BM25 sparse keyword retrieval, improving recall for both semantic and lexical queries. A cross-encoder re-ranking stage further refines document ordering before answer generation by the Google Gemini large language model. Experimental results demonstrate improved retrieval accuracy and reduced latency through seman-tic caching", ar8.doi="10.0000/mock-hyb-2", ar8.publication_date="2024-01-08", ar8.author_count=1, ar8.affiliation_count=1, ar8.corpus="UNIguide: An Intelligent University Information Retrieval Chatbot Using Advanced Retrieval-Augmented Generation with Hybrid Search and Neural Re-Ranking Accessing timely and accurate institutional infor-mation remains a challenge for students and faculty in en-gineering colleges. This paper presents UNIguide, a domain-specific intelligent chatbot designed to answer university-related queries using a Retrieval-Augmented Generation (RAG) pipeline integrating hybrid retrieval, neural re-ranking, query validation, and semantic caching. Hybrid retrieval combines dense vector search with BM25 sparse keyword retrieval, improving recall for both semantic and lexical queries. A cross-encoder re-ranking stage further refines document ordering before answer generation by the Google Gemini large language model. Experimental results demonstrate improved retrieval accuracy and reduced latency through seman-tic caching";
MERGE (ar9:Article {scopus_id:"MOCK-ART-9"}) SET ar9.title="A Hybrid Approach to Information Retrieval and Answer Generation for Regulatory Texts", ar9.abstract="Regulatory texts are inherently long and complex, presenting significant challenges for information retrieval systems in supporting regulatory officers with compliance tasks. This paper introduces a hybrid information retrieval system that combines lexical and semantic search techniques to extract relevant information from large regulatory corpora. The system integrates a fine-tuned sentence transformer model with the traditional BM25 algorithm to achieve both semantic precision and lexical coverage. To generate accurate and comprehensive responses, retrieved passages are synthesized using Large Language Models (LLMs) within a Retrieval Augmented Generation (RAG) framework. Experimental results demonstrate that the hybrid system significantly outperforms standalone lexical and semantic approaches, with notable improvements in Recall@10 and MAP@10. By openly sharing our fine-tuned model and methodology, we aim to advance the development of robust natural language processing tools for compliance-driven applications in regulatory domains.", ar9.doi="10.0000/mock-hyb-3", ar9.publication_date="2024-06-21", ar9.author_count=2, ar9.affiliation_count=1, ar9.corpus="A Hybrid Approach to Information Retrieval and Answer Generation for Regulatory Texts Regulatory texts are inherently long and complex, presenting significant challenges for information retrieval systems in supporting regulatory officers with compliance tasks. This paper introduces a hybrid information retrieval system that combines lexical and semantic search techniques to extract relevant information from large regulatory corpora. The system integrates a fine-tuned sentence transformer model with the traditional BM25 algorithm to achieve both semantic precision and lexical coverage. To generate accurate and comprehensive responses, retrieved passages are synthesized using Large Language Models (LLMs) within a Retrieval Augmented Generation (RAG) framework. Experimental results demonstrate that the hybrid system significantly outperforms standalone lexical and semantic approaches, with notable improvements in Recall@10 and MAP@10. By openly sharing our fine-tuned model and methodology, we aim to advance the development of robust natural language processing tools for compliance-driven applications in regulatory domains.";
MERGE (ar10:Article {scopus_id:"MOCK-ART-10"}) SET ar10.title="Database Indexing Using Deep Learning Algorithms", ar10.abstract="Automation of database indexing is a crucial component of modern database management systems that enhances search performance, scalability, and relevance in large-scale data environments. This paper explores the application of deep learning algorithms for building and optimizing vector indexes capable of automatic adaptation to changes in data structure and query patterns. An experimental comparison was conducted between traditional indexing methods (B-Tree, GIN in PostgreSQL) and vector-based indexing using Sentence-BERT embeddings implemented in FAISS and Milvus systems. The study involved constructing a corpus of 1–5 million text records and performing a series of tests to evaluate performance metrics, including average query time, latency (95th percentile), index size, memory usage, and the search completeness metric (recall@10) relative to the BM25 baseline search. The results revealed that vector indexing achieved up to 0.94 recall@10 with comparable query latency, significantly outperforming traditional approaches in semantic search efficiency. The practical contribution of this work lies in demonstrating the feasibility of hybrid DBMS architectures that combine traditional SQL indexing for fast filtering with vector-based methods for semantic refinement. This approach lays the foundation for the development of intelligent, self-optimizing databases capable of autonomous adaptation. Future research should focus on reinforcement learning for dynamic index restructuring, optimization of computational costs, and the integration of vector indexing into cloud-based and distributed systems.", ar10.doi="10.0000/mock-vec-1", ar10.publication_date="2022-10-30", ar10.author_count=2, ar10.affiliation_count=1, ar10.corpus="Database Indexing Using Deep Learning Algorithms Automation of database indexing is a crucial component of modern database management systems that enhances search performance, scalability, and relevance in large-scale data environments. This paper explores the application of deep learning algorithms for building and optimizing vector indexes capable of automatic adaptation to changes in data structure and query patterns. An experimental comparison was conducted between traditional indexing methods (B-Tree, GIN in PostgreSQL) and vector-based indexing using Sentence-BERT embeddings implemented in FAISS and Milvus systems. The study involved constructing a corpus of 1–5 million text records and performing a series of tests to evaluate performance metrics, including average query time, latency (95th percentile), index size, memory usage, and the search completeness metric (recall@10) relative to the BM25 baseline search. The results revealed that vector indexing achieved up to 0.94 recall@10 with comparable query latency, significantly outperforming traditional approaches in semantic search efficiency. The practical contribution of this work lies in demonstrating the feasibility of hybrid DBMS architectures that combine traditional SQL indexing for fast filtering with vector-based methods for semantic refinement. This approach lays the foundation for the development of intelligent, self-optimizing databases capable of autonomous adaptation. Future research should focus on reinforcement learning for dynamic index restructuring, optimization of computational costs, and the integration of vector indexing into cloud-based and distributed systems.";

